frappe.ui.form.on('Purchase Order', {
    setup(frm){
        set_filters(frm, 'custom_subcontracting_item_code', 'items', [['Item', 'is_stock_item', '=', 1], ['Item', 'is_sub_contracted_item', '=', 1]])
    },
    refresh(frm) {
        if (frm.doc.is_internal_supplier && frm.doc.docstatus == 1 && frm.doc.custom_is_subcontracting) {
            frm.add_custom_button('Sales Order (Job Work)', function() {
                frm.call({
                    method: 'quantbit_subcontracting.subcontracting_customization.create_sales_order_from_po_for_is_internal_supplier',
                    args: {
                        doc: frm.doc.name,
                    },
                    callback: function(resp) {
                        if (resp.message) {
                            frm.refresh_field();
                        }
                    }
                });
            }, __('Create'));
        }
        if(frm.doc.taxes_and_charges && frm.doc.taxes.length == 0 && frm.doc.custom_is_subcontracting){
            frm.trigger('taxes_and_charges');
            frm.save();
        }
    },
    custom_is_subcontracting(frm) {
        if(frm.doc.custom_is_subcontracting) {
            update_item_codes(frm);
        }
    }
});

frappe.ui.form.on('Purchase Order Item', {
    items_add(frm) {
        if(frm.doc.custom_is_subcontracting) {
            update_item_codes(frm);
        }
    },
    async custom_subcontracting_item_code(frm, cdt, cdn) {
        if (frm.doc.custom_is_subcontracting) {
            let row = locals[cdt][cdn];
            if (row.qty && row.custom_subcontracting_item_code) {
                try {
                    const response = await frappe.db.get_value("Item", row.custom_subcontracting_item_code, ['custom_finished_good_casting_weight']);
                    if (response.message && response.message.custom_finished_good_casting_weight) {
                        row.custom_subcontracting_item_total_weight = row.qty * response.message.custom_finished_good_casting_weight;
                    }
                } catch (error) {
                    console.error("Error fetching weight per unit:", error);
                }
            }
            frm.refresh_field('items');
        }
    },
    qty(frm, cdt, cdn){
        if(frm.doc.custom_is_subcontracting) {
            let row = locals[cdt][cdn];
            if(row.qty){
                row.custom_subcontracting_item_quantity = row.qty;
                row.custom_subcontracting_item_total_weight = row.qty * row.custom_subcontracting_item_weight_per_unit;
            }
            frm.refresh_field();
        }
    },
    custom_subcontracting_item_quantity(frm, cdt, cdn) {
        if(frm.doc.custom_is_subcontracting){
            let row = locals[cdt][cdn];
            if(row.custom_subcontracting_item_quantity){
                row.custom_subcontracting_item_total_weight = row.custom_subcontracting_item_quantity * row.custom_subcontracting_item_weight_per_unit;
            }
            frm.refresh_field()
        }
    },
});

function update_item_codes(frm) {
    frappe.db.get_value("Subcontracting Settings", { "company": frm.doc.company }, ['default_service_item', 'default_service_item_name', 'default_service_item_uom'])
        .then((response) => {
            if (response.message) {
                const default_item_code = response.message.default_service_item;
                const default_item_name = response.message.default_service_item_name;
                const default_item_uom = response.message.default_service_item_uom;
                
                frm.doc.items.forEach(function(itm) {
                    itm.item_code = default_item_code;
                    itm.item_name = default_item_name;  // Use the correct field for item name
                    itm.uom = default_item_uom;  // Use the correct field for UOM
                });
                frm.refresh_fields();
            } else {
                console.error("Subcontracting Settings not found for company:", frm.doc.company);
            }
        })
        .catch((error) => {
            console.error("Error fetching default_service_item: ", error);
        });
}

function set_filters(frm, DocTypeFieldName, DocTypeField, filters){
    if(DocTypeField !== 'None'){
        frm.set_query(DocTypeFieldName, DocTypeField, function(doc, cdt, cdn) {
            return {
                filters: filters
            };
        });
    } else{
        frm.set_query(DocTypeFieldName, function(doc) {
            return {
                filters: filters,
            };
        });
    }
}

frappe.ui.form.on('Sales Order', {
	custom_is_job_work(frm) {
		if(frm.doc.custom_is_job_work){
		    update_item_codes(frm);
		}
	},
	setup(frm){
        set_filters(frm, 'custom_job_work_item_code', 'items', [['Item', 'is_stock_item', '=', 1], ['Item', 'is_sub_contracted_item', '=', 1]])
    },
    refresh(frm) {
        if (frm.doc.is_internal_customer && frm.doc.docstatus == 1 && frm.doc.custom_is_job_work) {
            frm.add_custom_button('Purchase Order (Subcontacting)', function() {
                frm.call({
                    method: 'quantbit_subcontracting.subcontracting_customization.create_purchase_order_from_so_for_is_internal_supplier',
                    args: {
                        doc: frm.doc.name,
                    },
                    callback: function(resp) {
                        if (resp.message) {
                            console.log("Sales Order Created Successfully");
                        }
                    }
                });
            }, __('Create'));
        }
        if(frm.doc.taxes_and_charges && frm.doc.taxes.length == 0 && frm.doc.custom_is_job_work){
            frm.trigger('taxes_and_charges');
            frm.save();
        }
    }
})

frappe.ui.form.on('Sales Order Item', {
	items_add(frm) {
		if(frm.doc.custom_is_job_work){
		    update_item_codes(frm);
		}
	},
	qty(frm, cdt, cdn){
        if(frm.doc.custom_is_job_work){
            let row = locals[cdt][cdn];
            if(row.qty){
                row.custom_job_work_item_qty = row.qty;
                row.custom_subcontracting_item_total_weight = row.qty * row.custom_job_work_item_weight_per_unit;
            }
            frm.refresh_field()
        }
    },
    async custom_job_work_item_code(frm, cdt, cdn) {
        if (frm.doc.custom_is_job_work) {
            let row = locals[cdt][cdn];
            if (row.qty && row.custom_job_work_item_code) {
                try {
                    const response = await frappe.db.get_value("Item", row.custom_job_work_item_code, ['custom_finished_good_casting_weight']);
                    if (response.message && response.message.custom_finished_good_casting_weight) {
                        row.custom_job_work_item_total_weight = row.qty * response.message.custom_finished_good_casting_weight;
                    }
                } catch (error) {
                    console.error("Error fetching weight per unit:", error);
                }
            }
            frm.refresh_field('items');
        }
    },
})

function update_item_codes(frm) {
    frappe.db.get_value("Job Work Settings", {"company": frm.doc.company}, ['default_service_item', 'default_service_item_name', 'default_service_item_uom'])
        .then((response) => {
            if (response.message) {
                const default_item_code = response.message.default_service_item;
                const default_item_name = response.message.default_service_item_name;
                const default_item_uom = response.message.default_service_item_uom;

                frm.doc.items.forEach(function(itm) {
                    itm.item_code = default_item_code;
                    itm.item_name = default_item_name;
                    itm.uom = default_item_uom;
                });
                frm.refresh_fields();
            } else {
                console.error("Job Work Settings not found for company:", frm.doc.company);
            }
        })
        .catch((error) => {
            console.error("Error fetching default_service_item: ", error);
        });
}

function set_filters(frm, DocTypeFieldName, DocTypeField, filters){
    if(DocTypeField !== 'None'){
        frm.set_query(DocTypeFieldName, DocTypeField, function(doc, cdt, cdn) {
            return {
                filters: filters
            };
        });
    } else{
        frm.set_query(DocTypeFieldName, function(doc) {
            return {
                filters: filters,
            };
        });
    }
}
